// 本人私产遗赠页只给有限关系/资产投影，知情、受领和交割尚未由声明自动发生。
#include "family_bequest_commands.hpp"
#include "family_continuation_people4.hpp"
#include "succession_consent_source.hpp"
#include "resident/views/common_presentation.hpp"
#include <algorithm>
#include <limits>
namespace hanmo::resident {
namespace {
using V=BoundaryValue;
// 页面与回调绑定同一个世界代次，不把查阅当作声明提交。
V identity(const CommonStore& c){StableId world;const char* digits="0123456789abcdef";for(auto b:c.state().identity.world_id){world+=digits[b>>4];world+=digits[b&15];}const auto& id=c.state().identity;return boundary::obj({{"world_id",V{world}},{"execution_epoch",V{id.execution_epoch}},{"revision",V{id.revision}},{"tick",V{id.tick}}});}
Outcome<V> person(const CommonStore& c,const CommonCatalog& catalog,const StableId& id,const FamilyContinuationPeopleRead4* sources){const auto* actor=c.state().actors.find(id);auto name=CommonPresentation(c.state(),catalog).display_name(id);Integer age=-1;if(sources){auto actual=sources->read_current_age(id);if(!actual.ok)return {false,{},actual.error};age=actual.value.age_years;}else if(actor&&actor->birth_tick&&*actor->birth_tick>=-2147483647&&*actor->birth_tick<=c.tick())age=(c.tick()-*actor->birth_tick)/720;return {true,boundary::obj({{"actor_id",V{id}},{"name",V{name.ok?name.value:id}},{"age_years",V{age}},{"alive",V{actor&&actor->alive}},{"available",V{actor&&actor->available}}}),{}};}
// 每个列表独立有界，同一页不可能导出整本军旅/家产账。
V::Array page_of(V::Array all,Integer page){V::Array out;for(Integer i=page*16;i<std::min<Integer>(all.size(),page*16+16);++i)out.push_back(std::move(all[static_cast<std::size_t>(i)]));return out;}
}
Outcome<BoundaryValue> query_family_bequest_page(const CommonStore& c,const FamilyState& family,const FamilyDeathState& deaths,const FamilyDeathOriginRead& origin,const FamilyBequestPolicy& policy,const FamilyBequestState& state,const FamilyBequestPlayerRead& player,const CommonCatalog& catalog,Integer page,const FamilyLifeHistoryRead4* life4,const FamilyContinuationPeopleRead4* people){
    using namespace boundary;if(!policy.enabled)return {false,{},common_failure("FamilyBequestProfileRequired").error};if(page<0||page>255)return {false,{},common_failure("InvalidBequestPage").error};auto valid=validate_family_bequests(c,family,deaths,origin,policy,state,player,life4,people);if(!valid.ok)return {false,{},valid.error};const auto& actor=c.state().metadata.player_actor_id;const auto* current=c.actor(actor);if(!current)return {false,{},common_failure("UnknownActor").error};V::Array people_rows,goods,original_lots;
    for(const auto& child:family.children.rows()){auto relation=succession_adoption_basis(c,family,actor,child.first,c.tick());if(relation.ok){auto row=person(c,catalog,child.first,people);if(!row.ok)return {false,{},row.error};people_rows.push_back(std::move(row.value));}}
    auto own=[&](const Owner& owner){return owner.kind==Owner::Kind::actor&&owner.id==actor&&!owner.extra;};Integer spendable=0;bool source_owned=false;const auto* wallet=c.wallet(current->wallet_id);const auto* bag=c.inventory(current->inventory_id);if(wallet&&bag&&own(wallet->owner)&&own(bag->owner)){auto funds=c.spendable(wallet->id);if(!funds.ok)return {false,{},funds.error};spendable=funds.value;source_owned=true;OrderedTable<Integer> amounts;for(const auto& lot:bag->lots)if(own(lot.owner)&&lot.reserved_by==ReservationRef{}&&!lot.extra){auto* prior=amounts.find(lot.item_id);if(lot.quantity<0||(prior&&*prior>std::numeric_limits<Integer>::max()-lot.quantity))return {false,{},common_failure("BequestProjectionOverflow").error};amounts.set(lot.item_id,(prior?*prior:0)+lot.quantity);}for(const auto& row:amounts.rows())if(row.second>0)goods.push_back(obj({{"item_id",V{row.first}},{"quantity",V{row.second}}}));}
    StableId declaration_id;const auto* declared=active_family_bequest(state,actor,&declaration_id);V active=obj({});Integer original_count=0;if(declared){const auto& terms=declared->source.terms;auto revoke=preview_family_bequest_revocation(c,family,deaths,origin,policy,state,player,declaration_id,life4,people);for(const auto& lot:terms.lots)original_lots.push_back(obj({{"lot_id",V{lot.lot_id}},{"item_id",V{lot.item_id}},{"quantity",V{lot.quantity}}}));original_count=original_lots.size();auto beneficiary=person(c,catalog,terms.beneficiary_actor_id,people);if(!beneficiary.ok)return {false,{},beneficiary.error};active=obj({{"declaration_id",V{declaration_id}},{"beneficiary",std::move(beneficiary.value)},{"declared_tick",V{declared->source.tick}},{"money_limit",V{terms.money}},{"lots",V{page_of(std::move(original_lots),page)}},{"lot_count",V{original_count}},{"revoke_available",V{revoke.ok}},{"revoke_code",V{revoke.ok?StableId{}:revoke.error.original.code}}});}
    const Integer person_count=people_rows.size(),goods_count=goods.size();return {true,obj({{"actor_id",V{actor}},{"source_identity",identity(c)},{"page",V{page}},{"beneficiary_count",V{person_count}},{"goods_count",V{goods_count}},{"beneficiaries",V{page_of(std::move(people_rows),page)}},{"goods",V{page_of(std::move(goods),page)}},{"spendable_money",V{spendable}},{"declaration_available",V{source_owned&&current->alive&&current->available&&!declared}},{"active",std::move(active)},{"transferred",V{false}},{"reserved",V{false}}}),{}};
}
}
